    sentTo: [(x2) => `We sent it to ${x2}.`, (x2) => `${x2}-\u0D32\u0D47\u0D15\u0D4D\u0D15\u0D4D \u0D15\u0D4B\u0D21\u0D4D \u0D05\u0D2F\u0D1A\u0D4D\u0D1A\u0D41.`],
